  package     net . runelite . client . plugins . metronome ;   import    com . google . inject . Provides ;  import   javax . inject . Inject ;  import    net . runelite . api . Client ;  import    net . runelite . api . SoundEffectID ;  import     net . runelite . api . events . GameTick ;  import     net . runelite . client . config . ConfigManager ;  import     net . runelite . client . eventbus . Subscribe ;  import     net . runelite . client . plugins . Plugin ;  import     net . runelite . client . plugins . PluginDescriptor ;  import      net . runelite . client . ui . overlay . OverlayManager ;    @ PluginDescriptor  (  name = "Metronome" ,  description = "Play a sound on a specified tick to aid in efficient skilling and prayer flicking" ,  tags =  { "skilling" , "tick" , "timers" , "prayer" , "flick" } ,  enabledByDefault = false ) public class MetronomePlugin  extends Plugin  {    @ Inject private Client  client ;    @ Inject private MetronomePluginConfiguration  config ;    @ Inject private MetronomeOverlay  ovr ;    @ Inject private OverlayManager  overlayManager ;   private  int  tickCounter = 0 ;   private boolean  shouldTock = false ;   private boolean  currentColorGreen = false ;    @ Provides MetronomePluginConfiguration provideConfig  (  ConfigManager configManager )  {  return  configManager . getConfig  (  MetronomePluginConfiguration . class ) ; }    @ Override protected void startUp  ( )  throws Exception  {   overlayManager . add  ( ovr ) ; }    @ Override protected void shutDown  ( )  throws Exception  {   overlayManager . remove  ( ovr ) ; }    @ Subscribe public void onGameTick  (  GameTick tick )  {   currentColorGreen =  ! currentColorGreen ;  if  (   config . tickCount  ( ) == 0 )  {  return ; }  if  (    ++ tickCounter %  config . tickCount  ( ) == 0 )  {   int  previousVolume =  client . getSoundEffectVolume  ( ) ;  if  (  shouldTock &&   config . tockVolume  ( ) > 0 )  {   client . setSoundEffectVolume  (  config . tockVolume  ( ) ) ;   client . playSoundEffect  (  SoundEffectID . GE_DECREMENT_PLOP ,  config . tockVolume  ( ) ) ; } else  if  (   config . tickVolume  ( ) > 0 )  {   client . setSoundEffectVolume  (  config . tickVolume  ( ) ) ;   client . playSoundEffect  (  SoundEffectID . GE_INCREMENT_PLOP ,  config . tickVolume  ( ) ) ; }   client . setSoundEffectVolume  ( previousVolume ) ;   shouldTock =  ! shouldTock ; } }   public  int getTickCounter  ( )  {  return tickCounter ; }   public boolean getIsCurrentColorGreen  ( )  {  return currentColorGreen ; } }